package com.hmdp.ai.infrastructure.observability;import com.hmdp.ai.domain.observability.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.math.BigDecimal;import java.util.*;
@Repository public class JdbcRunInspectionAdapter implements RunInspectionPort {private final JdbcTemplate jdbc;public JdbcRunInspectionAdapter(JdbcTemplate jdbc){this.jdbc=jdbc;}public List<RunInspectionItem>nodeRuns(String t,String w,String r){return jdbc.query("select id,node_id,node_type,status,error_code,coalesce(error_message,output_json) summary,coalesce(timestampdiff(microsecond,started_at,finished_at)/1000,0) latency_ms,created_at from ai_node_run where tenant_id=? and workspace_id=? and run_id=? and deleted=0 order by created_at,id",(x,n)->item(x,"NODE",x.getString("node_id"),x.getString("node_type"),0,0),t,w,r);}public List<RunInspectionItem>modelCalls(String t,String w,String r){return jdbc.query("select id,node_run_id,concat(provider,':',model_name) name,status,error_code,coalesce(response_summary,request_summary) summary,latency_ms,input_tokens,output_tokens,created_at from ai_model_call where tenant_id=? and workspace_id=? and run_id=? and deleted=0 order by created_at,id",(x,n)->item(x,"MODEL",x.getString("node_run_id"),x.getString("name"),x.getLong("input_tokens"),x.getLong("output_tokens")),t,w,r);}public List<RunInspectionItem>toolCalls(String t,String w,String r){return jdbc.query("select id,node_run_id,concat(protocol,':',tool_id,':',tool_version) name,status,error_code,coalesce(result_summary,invocation_summary) summary,latency_ms,created_at from ai_tool_call where tenant_id=? and workspace_id=? and run_id=? and deleted=0 order by created_at,id",(x,n)->item(x,"TOOL",x.getString("node_run_id"),x.getString("name"),0,0),t,w,r);}public List<RunInspectionItem>retrievals(String t,String w,String r){return jdbc.query("select id,node_run_id,concat(knowledge_base_id,':',knowledge_base_version,':',index_version) name,status,error_code,query_summary summary,latency_ms,created_at from ai_retrieval_record where tenant_id=? and workspace_id=? and run_id=? and deleted=0 order by created_at,id",(x,n)->item(x,"RETRIEVAL",x.getString("node_run_id"),x.getString("name"),0,0),t,w,r);}public List<RunInspectionItem>artifacts(String t,String w,String r){return jdbc.query("select id,run_id reference_id,name,status,null error_code,concat(content_type,':',size_bytes) summary,0 latency_ms,created_at from ai_artifact where tenant_id=? and workspace_id=? and run_id=? and deleted=0 order by created_at,id",(x,n)->item(x,"ARTIFACT",x.getString("reference_id"),x.getString("name"),0,0),t,w,r);}public RunUsageSummary usage(String t,String w,String r){Map<String,Object>row=jdbc.queryForMap("select coalesce(sum(input_tokens),0) input_tokens,coalesce(sum(output_tokens),0) output_tokens,count(*) model_calls,coalesce((select count(*) from ai_tool_call where tenant_id=? and workspace_id=? and run_id=? and deleted=0),0) tool_calls,coalesce(sum(input_tokens*p.input_token_price/1000000+output_tokens*p.output_token_price/1000000),0) total_cost from ai_model_call c left join ai_model_profile p on p.id=c.model_profile_id where c.tenant_id=? and c.workspace_id=? and c.run_id=? and c.deleted=0",t,w,r,t,w,r);return new RunUsageSummary(number(row.get("input_tokens")),number(row.get("output_tokens")),number(row.get("model_calls")),number(row.get("tool_calls")),new BigDecimal(String.valueOf(row.get("total_cost"))));}
    private RunInspectionItem item(java.sql.ResultSet x,String category,String reference,String name,long input,long output)throws java.sql.SQLException{java.sql.Timestamp timestamp=x.getTimestamp("created_at");return new RunInspectionItem(x.getString("id"),category,reference,name,x.getString("status"),x.getString("error_code"),x.getString("summary"),x.getLong("latency_ms"),input,output,timestamp==null?null:timestamp.toInstant());}private long number(Object v){return v==null?0:((Number)v).longValue();}}
